#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/pm/pm.h>
#include <zephyr/pm/device.h>
#include <zephyr/pm/state.h>

#include <zephyr/device.h>
#include <zephyr/init.h>

static const struct device *dev_a;
static const struct device *dev_b;
static const struct device *dev_c;

static int device_a_init(const struct device *dev)
{
	dev_a = dev;
	return 0;
}

static int device_b_init(const struct device *dev)
{
	dev_b = dev;
	return 0;
}

static int device_c_init(const struct device *dev)
{
	dev_c = dev;
	return 0;
}

/*
 * Suspend order: B -> A -> C
 * Resume order: C -> A -> B
 */

static int device_a_pm_action(const struct device *dev, enum pm_device_action action)
{
	enum pm_device_state state_b, state_c;

	(void)pm_device_state_get(dev_b, &state_b);
	(void)pm_device_state_get(dev_c, &state_c);

	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		/* When A is suspended, B should be suspended and C active */
		zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED, "B should be suspended");
		zassert_not_equal(state_c, PM_DEVICE_STATE_SUSPENDED, "C should be active");
		break;
	case PM_DEVICE_ACTION_RESUME:
		/* When A is resumed, C should be active and B suspended */
		zassert_not_equal(state_c, PM_DEVICE_STATE_SUSPENDED, "C should be active");
		zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED, "B should be suspended");
		break;
	default:
		return -ENOTSUP;
	}

	return 0;
}

static int device_b_pm_action(const struct device *dev, enum pm_device_action action)
{
	enum pm_device_state state_a, state_c;

	(void)pm_device_state_get(dev_a, &state_a);
	(void)pm_device_state_get(dev_c, &state_c);

	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		/* When B is suspended, A and C should be active */
		zassert_not_equal(state_a, PM_DEVICE_STATE_SUSPENDED, "A should be active");
		zassert_not_equal(state_c, PM_DEVICE_STATE_SUSPENDED, "C should be active");
		break;
	case PM_DEVICE_ACTION_RESUME:
		/* When B is resumed, A and C should be active */
		zassert_not_equal(state_a, PM_DEVICE_STATE_SUSPENDED, "A should be active");
		zassert_not_equal(state_c, PM_DEVICE_STATE_SUSPENDED, "C should be active");
		break;
	default:
		return -ENOTSUP;
	}

	return 0;
}

static int device_c_pm_action(const struct device *dev, enum pm_device_action action)
{
	enum pm_device_state state_a, state_b;

	(void)pm_device_state_get(dev_a, &state_a);
	(void)pm_device_state_get(dev_b, &state_b);

	switch (action) {
	case PM_DEVICE_ACTION_SUSPEND:
		/* When C is suspended, A and B should be suspended */
		zassert_equal(state_a, PM_DEVICE_STATE_SUSPENDED, "A should be suspended");
		zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED, "B should be suspended");
		break;
	case PM_DEVICE_ACTION_RESUME:
		/* When C is resumed, A and B should be suspended */
		zassert_equal(state_a, PM_DEVICE_STATE_SUSPENDED, "A should be suspended");
		zassert_equal(state_b, PM_DEVICE_STATE_SUSPENDED, "B should be suspended");
		break;
	default:
		return -ENOTSUP;
	}

	return 0;
}

/*
 * Init order: C -> A -> B
 * This will result in suspend order: B -> A -> C
 */
PM_DEVICE_DEFINE(pm_device_a, device_a_pm_action);
DEVICE_DEFINE(pm_device_a, "pm_device_a", &device_a_init, PM_DEVICE_GET(pm_device_a),
	      NULL, APPLICATION, 1, NULL);

PM_DEVICE_DEFINE(pm_device_b, device_b_pm_action);
DEVICE_DEFINE(pm_device_b, "pm_device_b", &device_b_init, PM_DEVICE_GET(pm_device_b),
	      NULL, APPLICATION, 2, NULL);

PM_DEVICE_DEFINE(pm_device_c, device_c_pm_action);
DEVICE_DEFINE(pm_device_c, "pm_device_c", &device_c_init, PM_DEVICE_GET(pm_device_c),
	      NULL, APPLICATION, 0, NULL);


static void test_busy(void)
{
	pm_busy_set("test");
	zassert_true(pm_system_is_busy(), "PM should be busy");

	pm_busy_clear("test");
	zassert_false(pm_system_is_busy(), "PM should not be busy");
}

static void test_device_order(void)
{
	/*
	 * Entering suspend state should suspend devices in the reverse
	 * order of their initialization. The assertions in the PM action
	 * callbacks validate the order.
	 */
	pm_system_force_power_state(PM_STATE_SUSPEND_TO_IDLE);

	/*
	 * Coming back from suspend state should resume devices in the same
	 * order of their initialization. The assertions in the PM action
	 * callbacks validate the order.
	 */
}

ZTEST_SUITE(power_management_1cpu, NULL, NULL, NULL, NULL, NULL);

ZTEST(power_management_1cpu, test_busy)
{
	test_busy();
}

ZTEST(power_management_1cpu, test_device_order)
{
	test_device_order();
}
